function validate([s, t, k]) {
  if (s.length < 1 || s.length > 200000 || t.length !== s.length) return 's and t need the same length, from 1 to 2 * 10^5.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t use only lowercase letters.';
  if (k < 1 || k > s.length || s.length % k !== 0) return 'k must be at least 1 and divide s.length.';
  const counts = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) { counts[s.charCodeAt(i) - 97]++; counts[t.charCodeAt(i) - 97]--; }
  if (counts.some(c => c !== 0)) return 's and t must be anagrams of each other.';
  return null;
}

