function isPossibleToRearrange(s, t, k) {
  const size = s.length / k;
  const count = new Map();

  for (let start = 0; start < s.length; start += size) {
    const piece = s.slice(start, start + size);
    count.set(piece, (count.get(piece) ?? 0) + 1);
  }

  for (let start = 0; start < t.length; start += size) {
    const piece = t.slice(start, start + size);
    const left = count.get(piece) ?? 0;
    if (left === 0) {
      return false;
    }
    count.set(piece, left - 1);
  }
  return true;
}

