function isPossibleToRearrange(s, t, k) {
  // Cut both strings into their pieces, sort each list, and compare the sorted lists.
  const length = s.length / k;
  const cut = text => {
    const parts = [];
    for (let i = 0; i < text.length; i += length) parts.push(text.substring(i, i + length));
    return parts.sort();
  };
  const a = cut(s), b = cut(t);
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

