function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, large ? 2 + pick(4) : 1 + pick(3));
  const width = large ? [2, 3, 5, 10, 50, 1][pick(6)] : 1 + pick(3);
  const k = large ? Math.floor(10000 / width) - pick(5) : 1 + pick(5);
  const pieces = Array.from({ length: k }, () => Array.from({ length: width }, () => letters[pick(letters.length)]).join(''));
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) { const j = pick(i + 1); [list[i], list[j]] = [list[j], list[i]]; }
    return list;
  };
  const s = pieces.join('');
  const mode = pick(3);
  // 0: reorder the pieces (true); 1: any anagram of s (often false); 2: reorder, then swap two different letters (usually false).
  const chars = mode === 1 ? shuffle([...s]) : [...shuffle([...pieces]).join('')];
  if (mode === 2) {
    const i = pick(chars.length);
    const others = [];
    for (let j = 0; j < chars.length; j++) if (chars[j] !== chars[i]) others.push(j);
    if (others.length) { const j = others[pick(others.length)]; [chars[i], chars[j]] = [chars[j], chars[i]]; }
  }
  return [s, chars.join(''), k];
}
